inline const PrefabData* GetByPrefabPath(const char* path) noexcept
{
    if (!path) return nullptr;
    for (std::size_t i = 0; i < kCount; ++i)
        if (std::strcmp(kData[i].prefab_path, path) == 0) return &kData[i];
    return nullptr;
}

inline bool HasType(const PrefabData* prefab, const char* type) noexcept
{
    if (!prefab || !type) return false;
    for (std::size_t i = 0; i < prefab->type_count; ++i)
        if (std::strcmp(kTypeNames[prefab->first_type + i], type) == 0) return true;
    return false;
}

inline bool HasTypeByPrefabId(std::uint32_t prefab_id, const char* type) noexcept
{
    return HasType(GetByPrefabId(prefab_id), type);
}
